export function PricingTable({
  heading = "{{heading}}",
  highlightedPlan = "{{highlightedPlan}}",
  accent = "{{accent}}",
  annualBilling = {{annualBilling}},
}) {
  const plans = [
    { name: "Starter", monthly: 12, annual: 9 },
    { name: "Pro", monthly: 29, annual: 24 },
    { name: "Team", monthly: 59, annual: 49 },
  ];
  return (
    <section style={{ font: "15px system-ui, sans-serif", color: "#241430", padding: 24, textAlign: "center" }}>
      <h2 style={{ margin: "0 0 20px", fontSize: 22, fontWeight: 700 }}>{heading}</h2>
      <div style={{ display: "flex", gap: 16, justifyContent: "center" }}>
        {plans.map((plan) => {
          const active = plan.name === highlightedPlan;
          return (
            <div key={plan.name} style={{ flex: 1, maxWidth: 150, padding: 18, borderRadius: 12,
              border: `1.5px solid ${active ? accent : "#24143022"}`, background: active ? accent : "transparent",
              color: active ? "#FAF7F2" : "#241430" }}>
              <p style={{ margin: "0 0 6px", fontWeight: 700, fontSize: 13, textTransform: "uppercase", letterSpacing: "0.04em" }}>{plan.name}</p>
              <p style={{ margin: 0, fontSize: 24, fontWeight: 800 }}>
                ${annualBilling ? plan.annual : plan.monthly}<small style={{ fontSize: 12, fontWeight: 500, opacity: 0.75 }}>/mo</small>
              </p>
            </div>
          );
        })}
      </div>
    </section>
  );
}
